package dev.tiertagger.core;
import com.google.gson.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ProviderParsersTest {
 private static final UUID ID=UUID.fromString("74410533-05ec-40c8-894d-62b5555dde51");
 @Test void uuidIdentityAndHighLowRanks(){String profile="{\"uuid\":\""+ID+"\",\"rankings\":{\"crystal\":{\"tier\":4,\"pos\":1},\"nethop\":{\"tier\":3,\"pos\":0}}}";assertEquals(Map.of("crystal","LT4","nethpot","HT3"),ProviderParsers.parse("pvptiers",profile,ID));assertThrows(IllegalArgumentException.class,()->ProviderParsers.parse("pvptiers",profile,UUID.randomUUID()));}
 @Test void pvphqNeverShowsUnplayedModes(){String body="{\"_id\":\""+ID+"\",\"data\":{\"SWORD\":{\"gamesPlayed\":0,\"grantedTier\":\"LT5\"},\"MACE\":{\"gamesPlayed\":1,\"grantedTier\":\"HT4\"},\"AXE\":{\"grantedTier\":\"LT5\"}}}";assertEquals(Map.of("mace","HT4"),ProviderParsers.parse("pvphq",body,ID));}
 @Test void lucnoxityPreservesMidTier(){String body="{\"minecraftUUID\":\""+ID+"\",\"gamemodeProfiles\":[{\"gamemode\":{\"name\":\"crystalpvp\"},\"currentTier\":{\"tierNumber\":5,\"tierPosition\":\"MID\"}}]}";assertEquals("MT5",ProviderParsers.parse("lucnoxity",body,ID).get("crystal"));}
 @Test void conflictingSnapshotsDontInventRanksAndCrackedAccountsAreExcluded(){String one="{\"minecraftUuid\":\""+ID+"\",\"tiers\":{\"Sword\":\"HT2\",\"Modern SMP\":\"LT3\"}}",two=one.replace("HT2","LT4");assertEquals(Map.of("modern-smp","LT3"),ProviderParsers.snapshot("nova","["+one+","+two+"]").get(ID));String crack="{\"uuid\":\""+ID+"\",\"account\":\"Cracked\",\"tiers\":{\"Sword\":\"HT2\"}}";assertTrue(ProviderParsers.snapshot("crack","["+crack+"]").isEmpty());assertEquals("HT2",ProviderParsers.snapshot("crack","["+crack.replace("Cracked","Premium")+"]").get(ID).get("sword"));}
 @Test void mcpvpKeepsMidAndTierSixButRejectsMissingRanks(){String body="{\"players\":[{\"uuid\":\""+ID+"\",\"kitRanks\":{\"sword\":\"MT3\",\"mace\":\"HT6\",\"smp\":\"ST6\",\"axe\":\"???\"}}]}";assertEquals(Map.of("sword","MT3","mace","HT6","smp","ST6"),ProviderParsers.parse("mcpvp",body,ID));}
 @Test void prestigeDoesNotPickAnArbitraryGuildRank(){String body="{\"uuid\":\""+ID+"\",\"players\":[{\"uuid\":\""+ID+"\",\"tiers\":{\"sword\":\"LT3\"}},{\"uuid\":\""+ID+"\",\"tiers\":{\"sword\":\"HT1\"}}]}";assertTrue(ProviderParsers.parse("prestige",body,ID).isEmpty());}
 @Test void supportedDirectoryHasOrderedProvidersAndInvites(){assertEquals(List.of("mctiers","pvptiers","subtiers","lucnoxity","tiertests","mcpvp","pvphq","nova","prestige","lunar","nexus","jptiers","tiermc","crack"),ProviderCatalog.SUPPORTED.stream().map(ProviderCatalog.Provider::id).toList());assertTrue(ProviderCatalog.SUPPORTED.stream().allMatch(p->!p.discords().isEmpty()));assertFalse(ProviderCatalog.find("prime").supported());assertEquals("Elytra",ProviderCatalog.discordLabel("https://discord.gg/dn9YUKYbKH"));}
 @Test void paletteAndDistinctModes(){assertEquals(0x655b79,TierColors.color("LT4"));assertEquals(0xc4d3e7,TierColors.color("HT2"));assertEquals("diamond-op",ProviderParsers.mode("Diamond OP"));assertNotEquals(ProviderParsers.mode("Modern SMP"),ProviderParsers.mode("SMP"));assertEquals("tiertests.com",ProviderCatalog.name("tiertests"));}
}
